   790→JSOBJ JSON_DecodeObject(JSONObjectDecoder *dec, const char *buffer, size_t cbBuffer)
   791→{
   792→  /*
   793→  FIXME: Base the size of escBuffer of that of cbBuffer so that the unicode escaping doesn't run into the wall each time */
   794→  struct DecoderState ds;
   795→  JSUINT32 escBuffer[(JSON_MAX_STACK_BUFFER_SIZE / sizeof(JSUINT32))];
   796→  JSOBJ ret;
   797→
   798→  ds.start = (char *) buffer;
   799→  ds.end = ds.start + cbBuffer;
   800→
   801→  ds.escStart = escBuffer;
   802→  ds.escEnd = ds.escStart + (JSON_MAX_STACK_BUFFER_SIZE / sizeof(JSUINT32));
   803→  ds.escHeap = 0;
   804→  ds.prv = dec->prv;
   805→  ds.dec = dec;
   806→  ds.dec->errorStr = NULL;
   807→  ds.dec->errorOffset = NULL;
   808→  ds.objDepth = 0;
   809→
   810→  ds.dec = dec;
   811→
   812→  ret = decode_any (&ds);
   813→
   814→  if (ds.escHeap)
   815→  {
   816→    dec->free(ds.escStart);
   817→  }
   818→
   819→  if (!(dec->errorStr))
   820→  {
   821→    if ((ds.end - ds.start) > 0)
   822→    {
   823→      SkipWhitespace(&ds);
   824→    }
   825→
   826→    if (ds.start != ds.end && ret)
   827→    {
   828→      dec->releaseObject(ds.prv, ret);
   829→      return SetError(&ds, -1, "Trailing data");
   830→    }
   831→  }
   832→
   833→  return ret;
   834→}
